            {
              "kind": "paragraph",
              "children": [
                {
                  "kind": "span",
                  "text": "Return the pool string data associated with a catalog.  The data\n"
                },
                {
                  "kind": "span",
                  "text": "returned includes the contents of both the static and dynamic pools.\n"
                },
                {
                  "kind": "span",
                  "text": "The data returned can be used as the static pool data for a new\n"
                },
                {
                  "kind": "span",
                  "text": "catalog with messages defined via the Message_Indexes procedure\n"
                },
                {
                  "kind": "span",
                  "text": "(this functionality is only used in the zbmcompile application).\n"
                }
              ]
            }
