            {
              "kind": "paragraph",
              "children": [
                {
                  "kind": "span",
                  "text": "Load a set of localized files for a facility.  All files matching\n"
                },
                {
                  "kind": "span",
                  "text": "The base file name and extension and with locale name matching the\n"
                },
                {
                  "kind": "span",
                  "text": "given prefix are loaded.  E.g, \"myapp\", \"fr\" would match \"myapp_fr\"\n"
                },
                {
                  "kind": "span",
                  "text": "and \"myapp_fr_FR\", etc.\n"
                }
              ]
            }
